<script>document.querySelectorAll('form[method="post"]').forEach(function(form){form.addEventListener('submit',function(event){if(form.dataset.saving){event.preventDefault();return;}form.dataset.saving='1';form.querySelectorAll('button[type="submit"]').forEach(function(button){button.dataset.originalText=button.textContent;button.disabled=true;button.textContent='Saving…';});});});window.addEventListener('pageshow',function(){document.querySelectorAll('form[data-saving]').forEach(function(form){delete form.dataset.saving;form.querySelectorAll('button[type="submit"]').forEach(function(button){button.disabled=false;button.textContent=button.dataset.label||button.dataset.originalText||'Submit';});});});</script>
